import { Group, Mesh, PlaneGeometry, Color, PointLight, DoubleSide } from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const GroupCtor = THREE?.Group ?? Group;
  const PlaneCtor = THREE?.PlaneGeometry ?? PlaneGeometry;
  const MeshCtor = THREE?.Mesh ?? Mesh;
  const ColorCtor = THREE?.Color ?? Color;
  const PointLightCtor = THREE?.PointLight ?? PointLight;
  const DoubleSideVal = THREE?.DoubleSide ?? DoubleSide;

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new GroupCtor();
  root.name = 'journal-card-3';

  // ---- dimensions from atlas rect (512x320 -> 1.6 aspect) ----
  const cardW = 2.0;
  const cardH = cardW * (320 / 512);

  // ---- depth plane 1: ink backing plate (subject support) ----
  const backingGeo = new PlaneCtor(cardW * 1.03, cardH * 1.05, 1, 1);
  const backingMat = new MeshStandardNodeMaterial({
    color: new ColorCtor(colors.ink),
    roughness: 0.65,
    metalness: 0.2,
    side: DoubleSideVal,
  });
  const backingMesh = new MeshCtor(backingGeo, backingMat);
  backingMesh.position.set(0, 0, -0.06);
  root.add(backingMesh);

  // ---- depth plane 2 (foreground accent): thin accent edge frame ----
  const accentGeo = new PlaneCtor(cardW * 1.045, cardH * 1.065, 1, 1);
  const accentMat = new MeshStandardNodeMaterial({
    color: new ColorCtor(colors.accent),
    roughness: 0.5,
    metalness: 0.3,
    emissive: new ColorCtor(colors.accent),
    emissiveIntensity: 0.0,
    side: DoubleSideVal,
    transparent: true,
    opacity: 0.0,
  });
  const accentMesh = new MeshCtor(accentGeo, accentMat);
  accentMesh.position.set(0, 0, -0.07);
  root.add(accentMesh);

  // ---- depth plane 3: subject (the image itself) ----
  const cardGeo = new PlaneCtor(cardW, cardH, 1, 1);
  const cardMat = new MeshStandardNodeMaterial({
    color: new ColorCtor(colors.paper),
    roughness: 0.55,
    metalness: 0.15,
    side: DoubleSideVal,
  });
  const cardMesh = new MeshCtor(cardGeo, cardMat);
  cardMesh.position.set(0, 0, 0);
  root.add(cardMesh);

  // load texture (async, non-blocking)
  let loadedTexture = null;
  if (config?.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        loadedTexture = tex;
        cardMat.map = tex;
        cardMat.color = new ColorCtor('#ffffff');
        cardMat.needsUpdate = true;
      })
      .catch(() => {
        // keep paper-colored fallback plane on failure
      });
  }

  // ---- local rim/accent light (node-local, intensity capped) ----
  const rimLight = new PointLightCtor(new ColorCtor(colors.accent), 0.0, 3.0);
  rimLight.position.set(0.6, 0.4, 0.8);
  root.add(rimLight);

  // ---- base transform state for motion ----
  const baseY = 0;
  const baseScale = 1;
  root.scale.set(baseScale, baseScale, baseScale);

  // ---- entrance: weighted, subtle rise-in on load ----
  const timelines = [];
  root.position.y = baseY - 0.4;
  root.userData.opacity = 0;
  cardMat.transparent = true;
  cardMat.opacity = 0;
  backingMat.transparent = true;
  backingMat.opacity = 0;

  const entranceTl = gsap.timeline();
  entranceTl.to(root.position, {
    y: baseY,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);
  entranceTl.to([cardMat, backingMat], {
    opacity: 1,
    duration: 0.6,
    ease: 'power2.out',
    onUpdate: () => {
      cardMat.needsUpdate = true;
      backingMat.needsUpdate = true;
    },
  }, 0);
  timelines.push(entranceTl);

  // ---- hover: rise-in (subtle, 0.15 scene units) + accent edge focus ----
  let hoverTl = null;
  const handlePointerOver = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: baseY + 0.15,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
    hoverTl.to(root.rotation, {
      x: -0.03,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
    hoverTl.to(accentMat, {
      opacity: 0.9,
      emissiveIntensity: 1.1,
      duration: 0.3,
      ease: 'power2.out',
      onUpdate: () => { accentMat.needsUpdate = true; },
    }, 0);
    hoverTl.to(rimLight, {
      intensity: 1.2,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
    timelines.push(hoverTl);
  };

  const handlePointerOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: baseY,
      duration: 0.35,
      ease: 'power2.out',
    }, 0);
    hoverTl.to(root.rotation, {
      x: 0,
      duration: 0.35,
      ease: 'power2.out',
    }, 0);
    hoverTl.to(accentMat, {
      opacity: 0.0,
      emissiveIntensity: 0.0,
      duration: 0.35,
      ease: 'power2.out',
      onUpdate: () => { accentMat.needsUpdate = true; },
    }, 0);
    hoverTl.to(rimLight, {
      intensity: 0.0,
      duration: 0.35,
      ease: 'power2.out',
    }, 0);
    timelines.push(hoverTl);
  };

  // ---- press-down on click ----
  const handlePointerDown = () => {
    gsap.killTweensOf(root.scale);
    const pressTl = gsap.timeline();
    pressTl.to(root.scale, {
      x: baseScale * 0.97,
      y: baseScale * 0.97,
      z: baseScale * 0.97,
      duration: 0.12,
      ease: 'back.out(2)',
    });
    timelines.push(pressTl);
  };

  const handlePointerUp = () => {
    gsap.killTweensOf(root.scale);
    const releaseTl = gsap.timeline();
    releaseTl.to(root.scale, {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.35,
      ease: 'power4.out',
    }).to(root.scale, {
      x: baseScale,
      y: baseScale,
      z: baseScale,
      duration: 0.55,
      ease: 'power4.out',
    });
    timelines.push(releaseTl);
  };

  const handleClick = () => {
    ctx.emit('hub-journal.select', {
      nodeId: config?.id ?? 'journal-card-3',
      itemId: config?.dataBindings?.itemId ?? config?.id ?? 'journal-card-3',
    });
  };

  // ---- stock badge placeholder driven by trpc.inventory.status.inStock binding ----
  const badgeGeo = new PlaneCtor(0.22, 0.22, 1, 1);
  const badgeMat = new MeshStandardNodeMaterial({
    color: new ColorCtor(colors.accent),
    roughness: 0.5,
    metalness: 0.2,
    emissive: new ColorCtor(colors.accent),
    emissiveIntensity: 0.5,
    transparent: true,
    opacity: 0.0,
  });
  const badgeMesh = new MeshCtor(badgeGeo, badgeMat);
  badgeMesh.position.set(cardW * 0.5 - 0.16, cardH * 0.5 - 0.16, 0.02);
  root.add(badgeMesh);

  root.userData.setInStock = (inStock) => {
    gsap.to(badgeMat, {
      opacity: inStock ? 0.95 : 0.35,
      duration: 0.4,
      ease: 'power2.out',
      onUpdate: () => { badgeMat.needsUpdate = true; },
    });
    badgeMat.color = new ColorCtor(inStock ? colors.accent : colors.ink);
    badgeMat.needsUpdate = true;
  };

  // ---- apply any listed cinematic primitives (none configured, loop is safe) ----
  const primitiveHandles = [];
  const primitiveList = config?.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    if (prim?.name && ctx.primitives?.[prim.name]) {
      const handle = ctx.primitives[prim.name](root, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  root.userData.handlers = {
    pointerover: handlePointerOver,
    pointerout: handlePointerOut,
    pointerdown: handlePointerDown,
    pointerup: handlePointerUp,
    click: handleClick,
  };

  root.userData.cleanup = () => {
    for (const tl of timelines) {
      tl.kill();
    }
    gsap.killTweensOf(root.scale);
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.rotation);
    gsap.killTweensOf(accentMat);
    gsap.killTweensOf(badgeMat);
    gsap.killTweensOf(rimLight);

    for (const handle of primitiveHandles) {
      handle?.cleanup?.();
    }

    backingGeo.dispose();
    backingMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    cardGeo.dispose();
    cardMat.dispose();
    badgeGeo.dispose();
    badgeMat.dispose();

    if (loadedTexture) {
      loadedTexture.dispose();
    }

    root.remove(backingMesh, accentMesh, cardMesh, badgeMesh, rimLight);
  };

  return root;
}
